package com.srenterprises.controller; import com.srenterprises.entity.*; import com.srenterprises.repository.*; import org.springframework.data.domain.*; import org.springframework.security.access.prepost.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/audit-logs") @PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN')") public class AdminAuditController { final AuditLogRepository logs; AdminAuditController(AuditLogRepository l){logs=l;} @GetMapping public Page<AuditLog> list(@RequestParam(defaultValue="0") int page){return logs.findAll(PageRequest.of(page,25,Sort.by("createdAt").descending()));} }
